"use client";

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { auth } from '@/lib/firebase';
import { onAuthStateChanged } from 'firebase/auth';
import api from '@/lib/api';
import TopNav from '@/components/TopNav';
import BottomNav from '@/components/BottomNav';
import { useBakery } from '@/context/BakeryContext';
import Link from 'next/link';

interface InventoryItem {
  id: number;
  name: string;
  quantity: number;
  unit: string;
  purchase_price: number;
}

interface RecipeIngredient {
  id?: number;
  inventory_item_id: number;
  quantity_required: number;
  // UI only fields
  item_name?: string;
  unit?: string;
  purchase_price?: number;
}

interface Recipe {
  id: number;
  name: string;
  description: string;
  yield_amount: string;
  image_data?: string;
  prep_time_minutes?: number;
  bake_time_minutes?: number;
  use_custom_overheads?: boolean;
  custom_labor_cost?: number;
  custom_overhead_cost?: number;
  ingredients: RecipeIngredient[];
}

// Unit conversion helper
const calculateCost = (ingredient: RecipeIngredient, item: InventoryItem): number => {
  if (!item) return 0;

  let requiredQty = ingredient.quantity_required;
  const itemUnit = item.unit.toLowerCase();
  const ingUnit = ingredient.unit?.toLowerCase() || itemUnit;

  // Standardize common unit strings
  if (itemUnit === 'kg' && ingUnit === 'g') {
    requiredQty = requiredQty / 1000;
  } else if (itemUnit === 'g' && ingUnit === 'kg') {
    requiredQty = requiredQty * 1000;
  } else if (itemUnit === 'l' && ingUnit === 'ml') {
    requiredQty = requiredQty / 1000;
  } else if (itemUnit === 'ml' && ingUnit === 'l') {
    requiredQty = requiredQty * 1000;
  }

  return (requiredQty / item.quantity) * item.purchase_price;
};

export default function RecipesPage() {
  const router = useRouter();
  const { currencySymbol, profile: bakeryProfile } = useBakery();

  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<any>(null);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importSourceType, setImportSourceType] = useState('url'); // 'url' or 'photo'
  const [importSourceData, setImportSourceData] = useState('');
  const [geminiApiKey, setGeminiApiKey] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form State
  const [newRecipe, setNewRecipe] = useState<Partial<Recipe>>({
    name: '',
    description: '',
    yield_amount: '',
    image_data: '',
    prep_time_minutes: 0,
    bake_time_minutes: 0,
    use_custom_overheads: false,
    custom_labor_cost: 0,
    custom_overhead_cost: 0,
    ingredients: []
  });

  // Temp Ingredient selection
  const [selectedItemId, setSelectedItemId] = useState<number | ''>('');
  const [selectedItemQty, setSelectedItemQty] = useState<string>('');
  const [selectedItemUnit, setSelectedItemUnit] = useState<string>('g'); // Default input unit

  const fetchData = async () => {
    try {
      setLoading(true);
      const [recipesRes, inventoryRes] = await Promise.all([
        api.get('/recipes/'),
        api.get('/inventory/')
      ]);
      setRecipes(recipesRes.data);
      setInventory(inventoryRes.data);
    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const savedKey = localStorage.getItem('geminiApiKey');
    if (savedKey) setGeminiApiKey(savedKey);

    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        fetchData();
      } else {
        router.push('/login');
      }
    });
    return () => unsubscribe();
  }, [router]);

  const handleImportRecipe = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!geminiApiKey) {
      alert("Please provide a Gemini API Key");
      return;
    }

    localStorage.setItem('geminiApiKey', geminiApiKey);
    setIsImporting(true);

    try {
      const res = await api.post('/ai/import', {
        source_type: importSourceType,
        source_data: importSourceData
      }, {
        headers: {
          'x-gemini-api-key': geminiApiKey
        }
      });

      const parsed = res.data;
      if (parsed.warnings && parsed.warnings.length > 0) {
        alert("Imported with warnings:\n" + parsed.warnings.join("\n"));
        // Re-fetch inventory since new items might have been created
        fetchData();
      }

      setNewRecipe({
        name: parsed.name,
        description: parsed.description,
        yield_amount: parsed.yield_amount,
        prep_time_minutes: parsed.prep_time_minutes,
        bake_time_minutes: parsed.bake_time_minutes,
        use_custom_overheads: false,
        custom_labor_cost: 0,
        custom_overhead_cost: 0,
        ingredients: parsed.ingredients.map((ing: any) => ({
          inventory_item_id: ing.inventory_item_id,
          quantity_required: ing.quantity,
          unit: ing.unit
        }))
      });

      setIsImportModalOpen(false);
      setIsModalOpen(true);
    } catch (err: any) {
      console.error(err);
      alert(err.response?.data?.detail || "Failed to import recipe");
    } finally {
      setIsImporting(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 1024 * 1024) {
      alert("Image size must be less than 1MB.");
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setNewRecipe({ ...newRecipe, image_data: reader.result as string });
    };
    reader.readAsDataURL(file);
  };

  const addIngredientToRecipe = () => {
    if (!selectedItemId || !selectedItemQty) return;

    const item = inventory.find(i => i.id === Number(selectedItemId));
    if (!item) return;

    const newIngredient: RecipeIngredient = {
      inventory_item_id: item.id,
      quantity_required: Number(selectedItemQty),
      item_name: item.name,
      unit: selectedItemUnit,
      purchase_price: item.purchase_price
    };

    setNewRecipe({
      ...newRecipe,
      ingredients: [...(newRecipe.ingredients || []), newIngredient]
    });

    // Reset selections
    setSelectedItemId('');
    setSelectedItemQty('');
  };

  const removeIngredient = (index: number) => {
    const updatedIngredients = [...(newRecipe.ingredients || [])];
    updatedIngredients.splice(index, 1);
    setNewRecipe({ ...newRecipe, ingredients: updatedIngredients });
  };

  const handleSaveRecipe = async () => {
    if (!newRecipe.name || !newRecipe.ingredients || newRecipe.ingredients.length === 0) {
      alert("Please provide a name and at least one ingredient.");
      return;
    }

    try {
      setIsSubmitting(true);

      const payload = {
        ...newRecipe,
        ingredients: newRecipe.ingredients.map(ing => {
          const item = inventory.find(i => i.id === ing.inventory_item_id);
          let qty = ing.quantity_required;
          const ingUnit = ing.unit?.toLowerCase() || '';
          const itemUnit = item?.unit.toLowerCase() || '';

          if (itemUnit === 'kg' && ingUnit === 'g') {
            qty = qty / 1000;
          } else if (itemUnit === 'g' && ingUnit === 'kg') {
            qty = qty * 1000;
          } else if (itemUnit === 'l' && ingUnit === 'ml') {
            qty = qty / 1000;
          } else if (itemUnit === 'ml' && ingUnit === 'l') {
            qty = qty * 1000;
          }

          return {
            inventory_item_id: ing.inventory_item_id,
            quantity_required: qty
          };
        })
      };

      await api.post('/recipes/', payload);
      await fetchData();
      setIsModalOpen(false);
      setNewRecipe({ name: '', description: '', yield_amount: '', image_data: '', ingredients: [] });
    } catch (error) {
      console.error("Error saving recipe:", error);
      alert("Failed to save recipe. Please check your connection.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const deleteRecipe = async (id: number) => {
    if (!confirm("Are you sure you want to delete this recipe?")) return;
    try {
      await api.delete(`/recipes/${id}`);
      setRecipes(recipes.filter(r => r.id !== id));
    } catch (error) {
      console.error("Error deleting recipe:", error);
      alert("Failed to delete recipe.");
    }
  };

  const calculateTotalRecipeCost = (recipe: Partial<Recipe>) => {
    const ingredients = recipe.ingredients || [];
    const ingredientCost = ingredients.reduce((total, ing) => {
      const inventoryItem = inventory.find(i => i.id === ing.inventory_item_id);
      if (!inventoryItem) return total;
      return total + calculateCost({ ...ing, unit: ing.unit || inventoryItem.unit }, inventoryItem);
    }, 0);

    let laborCost = 0;
    let overheadCost = 0;

    if (recipe.use_custom_overheads) {
      laborCost = recipe.custom_labor_cost || 0;
      overheadCost = recipe.custom_overhead_cost || 0;
    } else {
      const baseLabor = profile?.base_hourly_labor_rate || 0;
      const energyRate = profile?.energy_cost_per_hour || 0;
      const miscPercent = profile?.misc_overhead_percentage ?? 5.0;

      const prepTime = recipe.prep_time_minutes || 0;
      const bakeTime = recipe.bake_time_minutes || 0;

      laborCost = (baseLabor / 60) * prepTime;
      const energyCost = (energyRate / 60) * bakeTime;
      overheadCost = energyCost + ((ingredientCost + laborCost + energyCost) * (miscPercent / 100));
    }

    return ingredientCost + laborCost + overheadCost;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col pb-20">
        <TopNav title="Recipes" />
        <div className="flex-1 flex justify-center items-center">
